# -*- coding: utf-8 -*-
"""Общие папки Samba.

Настройки хранятся в отдельном файле /etc/samba/archive-navigator.conf,
который подключается одной строкой include в smb.conf.  Модуль не зависит
от GTK: его же использует консольный помощник, запускаемый через pkexec.
"""
import json
import os
import re
import shlex
import shutil
import socket
import subprocess
import sys
import tempfile

SHARES_NAME = 'archive-navigator.conf'
DEFAULT_SMB_CONF = '/etc/samba/smb.conf'
MANAGED_HEADER = (
    '# Managed by Archive Navigator. Do not edit this file manually.\n'
    '# Included from smb.conf; shares are configured in folder properties.\n'
)
INCLUDE_COMMENT = '# Archive Navigator: shared folders (managed include)'
TRUE = {'yes', 'true', '1', 'on'}
FALSE = {'no', 'false', '0', 'off'}
RESERVED_NAMES = {'global', 'homes', 'printers', 'print$'}
FORBIDDEN_NAME = '\x00\r\n[]\\/:*?"<>|%#;='
FORBIDDEN_USER = '\x00\r\n[]/:*?"<>|%#;=,'


class ShareError(ValueError):
    """Ошибка настройки общего ресурса (текст можно перевести через _())."""


# ───────────────────────────── пути и окружение ─────────────────────────────
def smb_conf_path():
    env = os.environ.get('SZ_SAMBA_CONF')
    if env:
        return os.path.abspath(os.path.expanduser(env))
    exe = shutil.which('smbd')
    if exe:
        rc, out, _err = _run([exe, '-b'], 5)
        if rc == 0:
            for line in out.splitlines():
                if 'CONFIGFILE:' in line:
                    path = line.split(':', 1)[1].strip()
                    if path:
                        return os.path.realpath(path)
    return DEFAULT_SMB_CONF


def shares_conf_path():
    env = os.environ.get('SZ_SAMBA_SHARES')
    if env:
        return os.path.abspath(os.path.expanduser(env))
    directory = os.path.dirname(smb_conf_path()) or '/etc/samba'
    return os.path.join(directory, SHARES_NAME)


def samba_installed():
    return bool(shutil.which('smbd') and shutil.which('testparm'))


def can_apply():
    if os.geteuid() == 0 or os.environ.get('SZ_SAMBA_ALLOW_NONROOT') == '1':
        return True
    return bool(shutil.which('pkexec'))


def available():
    return samba_installed() and can_apply()


def unc_path(name):
    host = socket.gethostname() or 'localhost'
    return '\\\\%s\\%s' % (host, name)


# ───────────────────────────── запуск команд ─────────────────────────────
def _run(args, timeout=10):
    try:
        p = subprocess.run(args, stdin=subprocess.DEVNULL,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           timeout=timeout)
        return (p.returncode,
                p.stdout.decode('utf-8', 'replace'),
                p.stderr.decode('utf-8', 'replace'))
    except (OSError, subprocess.SubprocessError) as e:
        return -1, '', str(e)


def _read(path):
    try:
        with open(path, encoding='utf-8', errors='replace') as f:
            return f.read()
    except OSError:
        return ''


def _stat(path):
    try:
        return os.stat(path)
    except OSError:
        return None


def _mode(path):
    st = _stat(path)
    return (st.st_mode & 0o7777) if st is not None else 0o644


def _owner(path):
    st = _stat(path)
    return (st.st_uid, st.st_gid) if st is not None else None


def _write_atomic(path, text, mode=0o644, owner=None):
    directory = os.path.dirname(path) or '.'
    os.makedirs(directory, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix='.archive-navigator-', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='\n') as f:
            f.write(text)
        os.chmod(tmp, mode)
        if owner is not None:
            try:
                os.chown(tmp, owner[0], owner[1])
            except OSError:
                pass
        os.replace(tmp, path)
    finally:
        try:
            if os.path.exists(tmp):
                os.unlink(tmp)
        except OSError:
            pass


# ───────────────────────────── разбор и сборка конфига ─────────────────────────────
def parse_shares(text):
    """Список ресурсов из отдельного конфига (не из smb.conf)."""
    shares = []
    current = None
    for raw in (text or '').splitlines():
        line = raw.strip()
        if not line or line.startswith('#') or line.startswith(';'):
            continue
        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            current = {'name': name, 'path': '', 'comment': '',
                       'browseable': True, 'read_only': True,
                       'guest_ok': False, 'users': []}
            shares.append(current)
            continue
        if current is None or '=' not in line:
            continue
        key, value = line.split('=', 1)
        key = key.strip().lower()
        value = value.strip()
        if key == 'path':
            current['path'] = value
        elif key == 'comment':
            current['comment'] = value
        elif key in ('browseable', 'browsable'):
            current['browseable'] = value.lower() in TRUE
        elif key in ('read only', 'readonly'):
            current['read_only'] = value.lower() not in FALSE
        elif key in ('guest ok', 'public'):
            current['guest_ok'] = value.lower() in TRUE
        elif key == 'valid users':
            current['users'] = [u for u in re.split(r'[\s,]+', value) if u]
        elif key in ('writeable', 'writable'):
            current['read_only'] = value.lower() not in TRUE
    return [s for s in shares if s['name']]


def section_names(text):
    names = []
    for line in (text or '').splitlines():
        match = re.match(r'^\s*\[([^\]]+)\]\s*$', line)
        if match:
            names.append(match.group(1).strip())
    return names


def build_shares_text(shares):
    parts = [MANAGED_HEADER.rstrip('\n')]
    for share in sorted(shares, key=lambda s: s['name'].casefold()):
        lines = [
            '[%s]' % share['name'],
            '   path = %s' % share['path'],
            '   browseable = %s' % ('yes' if share.get('browseable', True) else 'no'),
            '   read only = %s' % ('yes' if share.get('read_only', True) else 'no'),
            '   guest ok = %s' % ('yes' if share.get('guest_ok') else 'no'),
        ]
        if share.get('comment'):
            lines.append('   comment = %s' % share['comment'])
        if share.get('users') and not share.get('guest_ok'):
            lines.append('   valid users = %s' % ', '.join(share['users']))
        lines += ['   create mask = 0664', '   directory mask = 0775']
        parts.append('\n'.join(lines))
    return '\n\n'.join(parts).rstrip('\n') + '\n'


def ensure_include(text, smb_conf, shares_conf):
    """Добавить include нашего файла в [global], если его ещё нет."""
    want = os.path.realpath(shares_conf)
    base = os.path.dirname(os.path.abspath(smb_conf))
    for line in (text or '').splitlines():
        match = re.match(r'^\s*include\s*=\s*(.*)$', line, re.I)
        if not match:
            continue
        try:
            values = shlex.split(match.group(1))
        except ValueError:
            values = match.group(1).split()
        for value in values:
            if not os.path.isabs(value):
                value = os.path.join(base, value)
            if os.path.realpath(value) == want:
                return text, False
    block = '%s\ninclude = %s\n' % (INCLUDE_COMMENT, shares_conf)
    lines = (text or '').splitlines(True)
    global_index = None
    for index, line in enumerate(lines):
        if re.match(r'^\s*\[\s*global\s*\]\s*(?:[#;].*)?$', line, re.I):
            global_index = index
            break
    if global_index is None:
        return '[global]\n' + block + '\n' + (text or ''), True
    insert_at = len(lines)
    for index in range(global_index + 1, len(lines)):
        if re.match(r'^\s*\[[^\]]+\]\s*(?:[#;].*)?$', lines[index]):
            insert_at = index
            break
    if insert_at > 0 and not lines[insert_at - 1].endswith('\n'):
        lines[insert_at - 1] += '\n'
    prefix = '' if insert_at == 0 or not lines[insert_at - 1].strip() else '\n'
    lines.insert(insert_at, prefix + block)
    return ''.join(lines), True


def include_present():
    smb_conf = smb_conf_path()
    text = _read(smb_conf)
    if not text:
        return False
    _text, added = ensure_include(text, smb_conf, shares_conf_path())
    return not added


# ───────────────────────────── проверка и нормализация ─────────────────────────────
def _real_path(path):
    try:
        return os.path.realpath(os.path.expanduser(str(path)))
    except (OSError, ValueError):
        return ''


def _safe_default_name(name):
    name = re.sub(r'[\[\]\\/:*?"<>|%#;=\x00-\x1f]+', '-', name or '')
    name = name.strip(' .-')
    return name[:80] or 'share'


def suggest_name(path):
    real = _real_path(path)
    base = _safe_default_name(os.path.basename(real) or 'share')
    used = {s['name'].casefold() for s in parse_shares(_read(shares_conf_path()))}
    used |= {n.casefold() for n in section_names(_read(smb_conf_path()))}
    if base.casefold() not in used:
        return base
    for index in range(2, 1000):
        candidate = '%s-%d' % (base, index)
        if candidate.casefold() not in used:
            return candidate
    return '%s-%d' % (base, os.getpid())


def normalize_share(data):
    """Проверить и привести параметры ресурса к безопасному виду."""
    path = _real_path(data.get('path'))
    if not path or not os.path.isabs(path) or path != path.strip():
        raise ShareError('Invalid folder path.')
    if not os.path.isdir(path):
        raise ShareError('The folder does not exist.')
    if path == '/':
        raise ShareError('The root folder cannot be shared.')
    if any(ch in path for ch in '\x00\r\n%'):
        raise ShareError('Invalid folder path.')

    name = str(data.get('name') or '').strip()
    if not name:
        raise ShareError('Share name cannot be empty.')
    if len(name) > 80:
        raise ShareError('Share name is too long.')
    if name.casefold() in RESERVED_NAMES:
        raise ShareError('This share name is reserved.')
    if name in ('.', '..') or any(ch in name for ch in FORBIDDEN_NAME):
        raise ShareError('Invalid share name.')

    comment = str(data.get('comment') or '').strip()
    if any(ch in comment for ch in '\x00\r\n%'):
        raise ShareError('Invalid comment.')
    comment = comment[:255]

    raw_users = data.get('users') or []
    if isinstance(raw_users, str):
        raw_users = re.split(r'[\s,]+', raw_users)
    users = []
    for user in raw_users:
        user = str(user).strip()
        if not user:
            continue
        if len(user) > 64 or any(ch in user for ch in FORBIDDEN_USER):
            raise ShareError('Invalid user list.')
        if user not in users:
            users.append(user)
    if len(users) > 100:
        raise ShareError('Too many users.')

    return {
        'path': path,
        'name': name,
        'comment': comment,
        'browseable': bool(data.get('browseable', True)),
        'read_only': bool(data.get('read_only', True)),
        'guest_ok': bool(data.get('guest_ok', False)),
        'users': users,
    }


def share_for_path(path):
    real = _real_path(path)
    for share in parse_shares(_read(shares_conf_path())):
        if share.get('path') and _real_path(share['path']) == real:
            return share
    return None


def share_by_name(name):
    wanted = str(name or '').casefold()
    for share in parse_shares(_read(shares_conf_path())):
        if share['name'].casefold() == wanted:
            return share
    return None


# ───────────────────────────── служба Samba ─────────────────────────────
def _smbd_running():
    if shutil.which('pgrep'):
        rc, _out, _err = _run(['pgrep', '-x', 'smbd'], 3)
        if rc == 0:
            return True
    if shutil.which('systemctl'):
        for unit in ('smbd', 'smb'):
            rc, _out, _err = _run(['systemctl', 'is-active', '--quiet', unit], 3)
            if rc == 0:
                return True
    return False


def service_status():
    if os.environ.get('SZ_SAMBA_SKIP_RELOAD') == '1':
        return 'skipped'
    if _smbd_running():
        return 'active'
    if shutil.which('systemctl'):
        for unit in ('smbd', 'smb'):
            rc, out, _err = _run(
                ['systemctl', 'list-unit-files', unit + '.service', '--no-legend'], 4)
            if rc == 0 and out.strip():
                return 'inactive'
        return 'unknown'
    return 'inactive'


def _start_service():
    if os.environ.get('SZ_SAMBA_SKIP_RELOAD') == '1':
        return {'ok': True, 'service': 'skipped'}
    if not shutil.which('systemctl'):
        return {'ok': False, 'error': 'Cannot start Samba service.',
                'detail': 'systemctl not found.'}
    errors = []
    for unit in ('smbd', 'smb'):
        rc, out, err = _run(['systemctl', 'start', unit], 20)
        if rc == 0:
            return {'ok': True, 'service': 'started'}
        errors.append((err or out).strip())
    return {'ok': False, 'error': 'Cannot start Samba service.',
            'detail': '\n'.join(e for e in errors if e)}


def reload_samba():
    if os.environ.get('SZ_SAMBA_SKIP_RELOAD') == '1':
        return {'service': 'skipped'}
    if _smbd_running():
        if shutil.which('smbcontrol'):
            rc, _out, _err = _run(['smbcontrol', 'all', 'reload-config'], 8)
            if rc == 0:
                return {'service': 'reloaded'}
        if shutil.which('systemctl'):
            for unit in ('smbd', 'smb'):
                rc, _out, _err = _run(['systemctl', 'is-active', '--quiet', unit], 3)
                if rc == 0:
                    rc, _out, _err = _run(['systemctl', 'reload', unit], 15)
                    if rc == 0:
                        return {'service': 'reloaded'}
        return {'service': 'active',
                'warning': 'Samba is running, but its configuration could not be reloaded.'}
    started = _start_service()
    if started.get('ok'):
        return started
    return {'service': 'inactive',
            'warning': 'Samba service is not running. Start it manually.'}


def start_service():
    return _invoke({'action': 'start'})


# ───────────────────────────── применение ─────────────────────────────
def _validate(smb_conf):
    exe = shutil.which('testparm')
    if not exe:
        return True, ''
    rc, out, err = _run([exe, '-s', smb_conf], 15)
    if rc == 0:
        return True, ''
    return False, (out + '\n' + err).strip()


def apply_request(request):
    """Выполнить запрос (вызывается root-помощником или напрямую от root)."""
    if not isinstance(request, dict):
        return {'ok': False, 'error': 'Invalid request.'}
    if (os.geteuid() != 0 and
            os.environ.get('SZ_SAMBA_ALLOW_NONROOT') != '1'):
        return {'ok': False, 'error': 'Root privileges are required.'}

    action = request.get('action')
    if action == 'start':
        return _start_service()
    if action not in ('save', 'remove'):
        return {'ok': False, 'error': 'Unknown action.'}

    smb_conf = smb_conf_path()
    shares_conf = shares_conf_path()
    if os.path.abspath(shares_conf) == os.path.abspath(smb_conf):
        return {'ok': False, 'error': 'Invalid Samba configuration paths.'}
    if any(ch.isspace() for ch in shares_conf):
        return {'ok': False, 'error': 'Invalid Samba configuration paths.'}

    try:
        data = normalize_share(request) if action == 'save' else None
        old_smb = _read(smb_conf)
        old_shares = _read(shares_conf)
        shares = parse_shares(old_shares)
        system_names = {n.casefold() for n in section_names(old_smb)
                        if n.casefold() != 'global'}

        if action == 'save':
            for share in shares:
                same_name = share['name'].casefold() == data['name'].casefold()
                same_path = (share.get('path') and
                             _real_path(share['path']) == data['path'])
                if same_name and not same_path:
                    raise ShareError('Share name is already used by another folder.')
            if data['name'].casefold() in system_names:
                raise ShareError(
                    'Share name is already used in the system Samba configuration.')
            shares = [s for s in shares
                      if not (s.get('path') and
                              _real_path(s['path']) == data['path'])]
            shares.append(data)
            result_name = data['name']
            result_path = data['path']
        else:
            name = str(request.get('name') or '').strip()
            path = _real_path(request.get('path')) if request.get('path') else ''
            if not name and not path:
                raise ShareError('Share name is required.')
            shares = [s for s in shares
                      if not ((name and s['name'].casefold() == name.casefold()) or
                              (path and s.get('path') and
                               _real_path(s['path']) == path))]
            result_name = name
            result_path = path

        new_shares = build_shares_text(shares)
        new_smb, include_added = ensure_include(old_smb, smb_conf, shares_conf)
        _write_atomic(shares_conf, new_shares, 0o644, _owner(smb_conf))
        _write_atomic(smb_conf, new_smb, _mode(smb_conf), _owner(smb_conf))
        ok, detail = _validate(smb_conf)
        if not ok:
            _write_atomic(shares_conf, old_shares, 0o644, _owner(smb_conf))
            _write_atomic(smb_conf, old_smb, _mode(smb_conf), _owner(smb_conf))
            return {'ok': False, 'error': 'Samba configuration is invalid.',
                    'detail': detail}
        service = reload_samba()
        return {'ok': True, 'action': action, 'name': result_name,
                'path': result_path, 'include_added': include_added,
                **service}
    except ShareError as e:
        return {'ok': False, 'error': str(e)}
    except OSError as e:
        return {'ok': False, 'error': str(e)}


def _invoke(request):
    if (os.geteuid() == 0 or
            os.environ.get('SZ_SAMBA_ALLOW_NONROOT') == '1'):
        return apply_request(request)
    pkexec = shutil.which('pkexec')
    if not pkexec:
        return {'ok': False, 'error': 'pkexec not found.'}
    entry = os.environ.get('SZ_APP_ENTRY') or os.path.abspath(sys.argv[0])
    if not os.path.isfile(entry):
        return {'ok': False, 'error': 'Application entry point not found.'}
    fd, request_path = tempfile.mkstemp(
        prefix='archive-navigator-samba-', suffix='.json')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            json.dump(request, f, ensure_ascii=False)
        os.chmod(request_path, 0o600)
        command = [pkexec, sys.executable or 'python3', entry,
                   '--samba-apply', request_path]
        try:
            proc = subprocess.run(command, stdin=subprocess.DEVNULL,
                                  stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE, timeout=120)
        except (OSError, subprocess.SubprocessError) as e:
            return {'ok': False, 'error': str(e)}
        out = proc.stdout.decode('utf-8', 'replace').strip()
        err = proc.stderr.decode('utf-8', 'replace').strip()
        result = None
        for line in reversed(out.splitlines()):
            line = line.strip()
            if line.startswith('{'):
                try:
                    result = json.loads(line)
                    break
                except ValueError:
                    pass
        if result is None:
            if proc.returncode in (126, 127):
                return {'ok': False, 'cancelled': True,
                        'error': 'Authentication was cancelled.'}
            return {'ok': False, 'error': err or out or 'Samba helper failed.'}
        return result
    finally:
        try:
            os.unlink(request_path)
        except OSError:
            pass


def apply_share(data):
    try:
        share = normalize_share(data)
    except ShareError as e:
        return {'ok': False, 'error': str(e)}
    share['action'] = 'save'
    return _invoke(share)


def remove_share(name=None, path=None):
    request = {'action': 'remove'}
    if name:
        request['name'] = name
    if path:
        request['path'] = path
    return _invoke(request)


def apply_request_file(path):
    """Точка входа консольного помощника: прочитать JSON и вернуть JSON."""
    try:
        with open(path, encoding='utf-8') as f:
            request = json.load(f)
        result = apply_request(request)
    except Exception as e:  # noqa: BLE001 — помощник обязан вернуть JSON
        result = {'ok': False, 'error': str(e)}
    sys.stdout.write(json.dumps(result, ensure_ascii=False) + '\n')
    sys.stdout.flush()
    return 0 if result.get('ok') else 1
